        v("semantic.banter.group.post_ent_wrap_1", "hoomans.banter.group.post_ent_wrap_1", "Agreed. Morale matters out here.", { combatReactionRole = "wrap", topic = "post_entertainment" }, 12, false),
        v("semantic.banter.group.post_looter_open_1", "hoomans.banter.group.post_looter_open_1", "Still can't believe those looters tried pulling {slot.broadcast.topic} on {slot.broadcast.channel}, {addressee.name}.", { combatReactionRole = "open", topic = "post_looter_trap" }, 12, true),
        v("semantic.banter.group.post_looter_reply_1", "hoomans.banter.group.post_looter_reply_1", "Yeah, {addressee.name}. Good thing we spotted it for the ambush it was.", { combatReactionRole = "reply", topic = "post_looter_trap" }, 12, true),
        v("semantic.banter.group.post_looter_chime_1", "hoomans.banter.group.post_looter_chime_1", "Just hope nobody else falls for their free supplies routine.", { combatReactionRole = "chime", topic = "post_looter_trap" }, 12, false),
        v("semantic.banter.group.post_looter_wrap_1", "hoomans.banter.group.post_looter_wrap_1", "Lesson learned. Trust our instincts.", { combatReactionRole = "wrap", topic = "post_looter_trap" }, 12, false),
        v("semantic.banter.group.post_trader_open_1", "hoomans.banter.group.post_trader_open_1", "Think we should try to catch up with {slot.broadcast.topic} we heard earlier, {addressee.name}?", { combatReactionRole = "open", topic = "post_trader_radio" }, 12, true),
        v("semantic.banter.group.post_trader_reply_1", "hoomans.banter.group.post_trader_reply_1", "Could be worth it, {addressee.name}, if we've got spare gear to trade.", { combatReactionRole = "reply", topic = "post_trader_radio" }, 12, true),
        v("semantic.banter.group.post_trader_chime_1", "hoomans.banter.group.post_trader_chime_1", "A fair trade beats kicking down ten locked doors any day.", { combatReactionRole = "chime", topic = "post_trader_radio" }, 12, false),
        v("semantic.banter.group.post_trader_wrap_1", "hoomans.banter.group.post_trader_wrap_1", "Keep it in mind on our next run.", { combatReactionRole = "wrap", topic = "post_trader_radio" }, 12, false),
        v("semantic.banter.group.post_refugee_open_1", "hoomans.banter.group.post_refugee_open_1", "Still thinking about {slot.broadcast.topic} we heard earlier, {addressee.name}. Hope those folks are holding on.", { combatReactionRole = "open", topic = "post_refugee_radio" }, 12, true),
        v("semantic.banter.group.post_refugee_reply_1", "hoomans.banter.group.post_refugee_reply_1", "Me too, {addressee.name}. It's rough enough out here with a solid crew.", { combatReactionRole = "reply", topic = "post_refugee_radio" }, 12, true),
        v("semantic.banter.group.post_refugee_chime_1", "hoomans.banter.group.post_refugee_chime_1", "If we cross paths with them, maybe we can lend a hand.", { combatReactionRole = "chime", topic = "post_refugee_radio" }, 12, false),
        v("semantic.banter.group.post_refugee_wrap_1", "hoomans.banter.group.post_refugee_wrap_1", "Yeah. Let's keep our eyes open for them.", { combatReactionRole = "wrap", topic = "post_refugee_radio" }, 12, false),
        v("semantic.banter.group.post_settle_open_1", "hoomans.banter.group.post_settle_open_1", "Hearing {slot.broadcast.topic} earlier was a good sign, {addressee.name}. People are actually rebuilding.", { combatReactionRole = "open", topic = "post_settlement_radio" }, 12, true),
        v("semantic.banter.group.post_settle_reply_1", "hoomans.banter.group.post_settle_reply_1", "Gives you a little hope, {addressee.name}. Might be worth visiting them when we're ready.", { combatReactionRole = "reply", topic = "post_settlement_radio" }, 12, true),
        v("semantic.banter.group.post_settle_chime_1", "hoomans.banter.group.post_settle_chime_1", "Just remember to announce ourselves so their guards don't get twitchy.", { combatReactionRole = "chime", topic = "post_settlement_radio" }, 12, false),
        v("semantic.banter.group.post_settle_wrap_1", "hoomans.banter.group.post_settle_wrap_1", "Smart. Respect their perimeter.", { combatReactionRole = "wrap", topic = "post_settlement_radio" }, 12, false),
        v("semantic.banter.group.post_drama_open_1", "hoomans.banter.group.post_drama_open_1", "Still laughing about {slot.broadcast.topic} earlier, {addressee.name}. Glad our crew doesn't air our laundry on an open frequency.", { combatReactionRole = "open", topic = "post_radio_drama" }, 12, true),
        v("semantic.banter.group.post_drama_reply_1", "hoomans.banter.group.post_drama_reply_1", "No kidding, {addressee.name}. Last thing we need is half the county listening to us argue.", { combatReactionRole = "reply", topic = "post_radio_drama" }, 12, true),
        v("semantic.banter.group.post_drama_chime_1", "hoomans.banter.group.post_drama_chime_1", "At least we know those groups are too busy fighting each other to bother us.", { combatReactionRole = "chime", topic = "post_radio_drama" }, 12, false),
        v("semantic.banter.group.post_drama_wrap_1", "hoomans.banter.group.post_drama_wrap_1", "True enough. Let's keep our own house in order.", { combatReactionRole = "wrap", topic = "post_radio_drama" }, 12, false),
        v("semantic.banter.group.post_num_open_1", "hoomans.banter.group.post_num_open_1", "That {slot.broadcast.topic} we caught on {slot.broadcast.channel} still gives me chills, {addressee.name}.", { combatReactionRole = "open", topic = "post_numbers_station" }, 12, true),
        v("semantic.banter.group.post_num_reply_1", "hoomans.banter.group.post_num_reply_1", "Same, {addressee.name}. Wonder if anybody's actually left on the other end decoding it.", { combatReactionRole = "reply", topic = "post_numbers_station" }, 12, true),
        v("semantic.banter.group.post_num_chime_1", "hoomans.banter.group.post_num_chime_1", "Probably just some bunker tape spinning until the generators die.", { combatReactionRole = "chime", topic = "post_numbers_station" }, 12, false),
        v("semantic.banter.group.post_num_wrap_1", "hoomans.banter.group.post_num_wrap_1", "Either way, I'd rather not find out.", { combatReactionRole = "wrap", topic = "post_numbers_station" }, 12, false),
        v("semantic.banter.group.post_cann_open_1", "hoomans.banter.group.post_cann_open_1", "I still can't get {slot.broadcast.topic} out of my head, {addressee.name}. Sick world we're living in.", { combatReactionRole = "open", topic = "post_cannibal_radio" }, 12, true),
        v("semantic.banter.group.post_cann_reply_1", "hoomans.banter.group.post_cann_reply_1", "Don't dwell on them, {addressee.name}, just stay sharp so we never end up in their sights.", { combatReactionRole = "reply", topic = "post_cannibal_radio" }, 12, true),
        v("semantic.banter.group.post_cann_chime_1", "hoomans.banter.group.post_cann_chime_1", "We stick together and nobody touches us.", { combatReactionRole = "chime", topic = "post_cannibal_radio" }, 12, false),
        v("semantic.banter.group.post_cann_wrap_1", "hoomans.banter.group.post_cann_wrap_1", "Damn right. Watch each other's backs.", { combatReactionRole = "wrap", topic = "post_cannibal_radio" }, 12, false),
        v("semantic.banter.group.post_pastor_open_1", "hoomans.banter.group.post_pastor_open_1", "Wonder if {slot.broadcast.topic} is still out there preaching, {addressee.name}.", { combatReactionRole = "open", topic = "post_pastor_radio" }, 12, true),
        v("semantic.banter.group.post_pastor_reply_1", "hoomans.banter.group.post_pastor_reply_1", "Hard to say, {addressee.name}. Everybody holds onto whatever keeps them going.", { combatReactionRole = "reply", topic = "post_pastor_radio" }, 12, true),
        v("semantic.banter.group.post_pastor_chime_1", "hoomans.banter.group.post_pastor_chime_1", "Hope he's got solid walls around his church, though.", { combatReactionRole = "chime", topic = "post_pastor_radio" }, 12, false),
        v("semantic.banter.group.post_pastor_wrap_1", "hoomans.banter.group.post_pastor_wrap_1", "Yeah. Prayers and barricades both help.", { combatReactionRole = "wrap", topic = "post_pastor_radio" }, 12, false),
        v("semantic.banter.group.friction_reply_1", "hoomans.banter.group.friction_reply_1", "Easy for you to say, {addressee.name}. Maybe try pulling your weight before lecturing the rest of us.", { combatReactionRole = "reply_friction" }, 11, true),
        v("semantic.banter.group.friction_reply_2", "hoomans.banter.group.friction_reply_2", "Cut it out, {addressee.name}. Talking nonstop isn't gonna keep the dead off our backs.", { combatReactionRole = "reply_friction" }, 11, true),
        v("semantic.banter.group.friction_reply_3", "hoomans.banter.group.friction_reply_3", "I don't need a pep talk right now, {addressee.name}. Just focus on watching your own flank.", { combatReactionRole = "reply_friction" }, 11, true),
        v("semantic.banter.group.friction_defuse_1", "hoomans.banter.group.friction_defuse_1", "Hey, both of you, cool it. We're all tired, don't start snapping at each other.", { combatReactionRole = "chime_defuse" }, 11, false),
        v("semantic.banter.group.friction_defuse_2", "hoomans.banter.group.friction_defuse_2", "Take a breath. The dead are bad enough without us picking fights with our own people.", { combatReactionRole = "chime_defuse" }, 11, false),
        v("semantic.banter.group.friction_defuse_3", "hoomans.banter.group.friction_defuse_3", "Enough, save that energy for the next horde. We need each other sharp.", { combatReactionRole = "chime_defuse" }, 11, false),
        v("semantic.banter.group.friction_escalate_1", "hoomans.banter.group.friction_escalate_1", "Honestly? They've got a point. Somebody had to say it.", { combatReactionRole = "chime_escalate" }, 11, false),
        v("semantic.banter.group.friction_escalate_2", "hoomans.banter.group.friction_escalate_2", "If you two keep bickering, you're gonna draw every walker on this street.", { combatReactionRole = "chime_escalate" }, 11, false),
        v("semantic.banter.group.default", "hoomans.banter.group.default", "Stay close and keep your eyes open.", nil, 5, false),
    },
})

